  fn c007_invariant_dev_flexibility() {
      let dev = VersionPolicy::new("0.5.0").expect("valid semver");
      assert!(dev.is_breaking_change_allowed(), "Dev must allow breaking changes");
      assert!(dev.is_changelog_required(&ChangeKind::Major), "Dev breaking changes need CHANGELOG");

      let stable = VersionPolicy::new("1.2.0").expect("valid semver");
      assert!(!stable.is_breaking_change_allowed(), "Stable must reject MAJOR changes");
      assert!(!stable.is_changelog_required(&ChangeKind::Patch), "PATCH does not need CHANGELOG");

      // Security exception: security fix = Patch even in Stable
      let security_patch = classify_change("Security: fix buffer overflow in RTP parsing").expect("valid");
      assert_eq!(security_patch, ChangeKind::Patch, "security fix must be PATCH");

      // Runtime behavior change = Patch even in Stable
      let runtime_change = classify_change("Adjust default command timeout from 10s to 15s").expect("valid");
      assert_eq!(runtime_change, ChangeKind::Patch, "runtime behavior change must be PATCH");
  }
